input.content:
:root {
  --ink: #0a0d12;
  --ink-2: #11161e;
  --panel: rgba(10, 14, 20, 0.72);
  --panel-solid: #121820;
  --line: rgba(178, 207, 220, 0.2);
  --line-strong: rgba(196, 224, 236, 0.38);
  --text: #e7edf0;
  --muted: #8e9ca3;
  --amber: #ffb24a;
  --amber-hot: #ffd082;
  --orange: #ff6a2a;
  --cyan: #75e8ff;
  --green: #91f7b1;
  --red: #ff5e4d;
  --shadow: 0 24px 90px rgba(0, 0, 0, 0.48);
  --condensed: "Arial Narrow", "Roboto Condensed", "Liberation Sans Narrow", "Helvetica Neue", sans-serif;
  --mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #080b10;
  color: var(--text);
  font-family: var(--condensed);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

button { font: inherit; color: inherit; }
button:focus-visible { outline: 2px solid var(--amber); outline-offset: 3px; }

#world {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
  background: #080b10;
}

.screen-shade {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    linear-gradient(180deg, rgba(4, 8, 14, 0.54) 0%, transparent 15%, transparent 78%, rgba(4, 8, 14, 0.36) 100%),
    radial-gradient(circle at 50% 47%, transparent 35%, rgba(2, 5, 10, 0.34) 100%);
  mix-blend-mode: normal;
}

.scanlines {
  position: fixed;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: 0.12;
  background: repeating-linear-gradient(180deg, transparent 0 2px, rgba(170, 220, 255, 0.045) 3px, transparent 4px);
  mix-blend-mode: overlay;
}

.hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.7s ease;
}
body.playing .hud { opacity: 1; }

.panel {
  background:
    linear-gradient(145deg, rgba(25, 33, 43, 0.8), rgba(8, 12, 18, 0.78)),
    repeating-linear-gradient(135deg, rgba(255,255,255,0.018) 0 1px, transparent 1px 5px);
  border: 1px solid var(--line);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.25), inset 0 1px 0 rgba(255,255,255,0.06);
  backdrop-filter: blur(10px);
}

.hud-top {
  position: absolute;
  left: 24px;
  right: 24px;
  top: 20px;
  display: grid;
  grid-template-columns: minmax(230px, 0.9fr) minmax(350px, 1.45fr) minmax(240px, 0.9fr);
  gap: 18px;
  align-items: start;
}

.brand-panel {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 10px 14px;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  min-height: 57px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(255, 178, 74, 0.6);
  background: linear-gradient(135deg, rgba(255, 178, 74, 0.18), transparent);
  color: var(--amber);
  font: 700 13px/1 var(--mono);
  letter-spacing: -1px;
}

.brand-name {
  font-weight: 900;
  font-size: 20px;
  letter-spacing: 0.16em;
  line-height: 1;
}
.brand-sub {
  margin-top: 5px;
  color: var(--muted);
  font: 600 8.5px/1 var(--mono);
  letter-spacing: 0.1em;
}

.depth-panel {
  padding: 11px 18px 10px;
  clip-path: polygon(10px 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%, 0 10px);
}
.depth-readout {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}
.micro-label {
  font: 600 8px/1 var(--mono);
  letter-spacing: 0.16em;
  color: var(--muted);
  text-transform: uppercase;
}
.depth-value {
  color: var(--text);
  font: 800 26px/0.9 var(--condensed);
  letter-spacing: 0.04em;
}
.depth-value em {
  font-size: 11px;
  color: var(--muted);
  font-style: normal;
  margin-left: 3px;
  letter-spacing: 0.12em;
}
.depth-target {
  color: var(--muted);
  font: 600 8px/1 var(--mono);
  letter-spacing: 0.08em;
}

.depth-track {
  position: relative;
  height: 8px;
  margin: 10px 0 8px;
  background: linear-gradient(90deg, rgba(255,255,255,0.09), rgba(255,255,255,0.03));
  border: 1px solid rgba(255,255,255,0.08);
}
.depth-fill {
  position: absolute;
  inset: 1px auto 1px 1px;
  width: 0%;
  background: linear-gradient(90deg, #8e5a20, var(--amber) 62%, var(--amber-hot));
  box-shadow: 0 0 14px rgba(255, 178, 74, 0.4);
  transition: width 0.35s ease;
}
.depth-marker {
  position: absolute;
  top: -3px;
  left: 0%;
  width: 1px;
  height: 12px;
  background: var(--amber-hot);
  box-shadow: 0 0 10px var(--amber);
  transform: translateX(-1px);
  transition: left 0.35s ease;
}
.depth-marker i {
  position: absolute;
  top: -4px;
  left: -2px;
  width: 5px;
  height: 5px;
  transform: rotate(45deg);
  background: var(--amber-hot);
}
.depth-tick { position: absolute; top: 0; bottom: 0; width: 1px; background: rgba(0,0,0,0.5); }
.depth-tick.t1 { left: 33.3%; }
.depth-tick.t2 { left: 66.6%; }
.depth-tick.t3 { left: 86%; }
.depth-meta {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  color: var(--muted);
  font: 600 8px/1 var(--mono);
  letter-spacing: 0.09em;
}
#layer-name { color: #c8b08c; }

.resource-panel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 14px;
  min-height: 57px;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
}
.resource {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px;
}
.resource + .resource { border-left: 1px solid rgba(255,255,255,0.08); }
.resource-icon {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border: 1px solid rgba(255,255,255,0.15);
  background: rgba(255,255,255,0.03);
  color: var(--amber);
  font: 800 12px/1 var(--mono);
}
.cash-icon { color: var(--green); }
.fuel-icon { position: relative; }
.fuel-icon::before {
  content: "";
  width: 11px;
  height: 15px;
  border: 1px solid var(--amber);
  border-radius: 1px;
  background: linear-gradient(180deg, transparent 38%, rgba(255,178,74,0.45) 39%);
}
.fuel-icon::after {
  content: "";
  position: absolute;
  width: 4px;
  height: 3px;
  top: 4px;
  left: 15px;
  border: 1px solid var(--amber);
  border-left: 0;
}
.tier-icon { font-size: 9px; letter-spacing: -0.05em; }
.resource strong {
  display: block;
  margin-top: 3px;
  font: 800 18px/1 var(--condensed);
  letter-spacing: 0.06em;
}
.resource strong small { color: var(--muted); font-size: 8px; letter-spacing: 0.05em; }

.cue {
  position: absolute;
  left: 50%;
  top: 112px;
  transform: translateX(-50%);
  color: rgba(220, 232, 236, 0.34);
  font: 600 8px/1 var(--mono);
  letter-spacing: 0.26em;
  white-space: nowrap;
}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 42px;
  height: 42px;
  transform: translate(-50%, -50%);
  opacity: 0.75;
  transition: opacity 0.2s ease;
}
.ch {
  position: absolute;
  background: rgba(239, 246, 248, 0.9);
  box-shadow: 0 0 3px rgba(0,0,0,0.6);
  transition: transform 0.15s ease, background 0.2s ease;
}
.ch-top, .ch-bottom { width: 1px; height: 6px; left: 50%; }
.ch-left, .ch-right { width: 6px; height: 1px; top: 50%; }
.ch-top { top: 8px; }
.ch-bottom { bottom: 8px; }
.ch-left { left: 8px; }
.ch-right { right: 8px; }
.ch-dot {
  position: absolute;
  left: 50%; top: 50%;
  width: 3px; height: 3px;
  transform: translate(-50%, -50%);
  background: var(--amber-hot);
  border-radius: 50%;
  box-shadow: 0 0 5px var(--amber);
}
.crosshair.active .ch-top { transform: translateY(-4px); background: var(--amber-hot); }
.crosshair.active .ch-bottom { transform: translateY(4px); background: var(--amber-hot); }
.crosshair.active .ch-left { transform: translateX(-4px); background: var(--amber-hot); }
.crosshair.active .ch-right { transform: translateX(4px); background: var(--amber-hot); }

.drill-ring {
  --p: 0%;
  position: absolute;
  inset: -14px;
  border-radius: 50%;
  background: conic-gradient(var(--amber) var(--p), transparent 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2px));
  opacity: 0;
  transition: opacity 0.15s;
  transform: rotate(-90deg);
}
.crosshair.drilling .drill-ring { opacity: 1; }

.mine-readout {
  position: absolute;
  left: 50%;
  top: calc(50% + 48px);
  width: 250px;
  transform: translateX(-50%);
  padding: 8px 12px 9px;
  opacity: 0;
  transition: opacity 0.25s;
}
body.underground .mine-readout { opacity: 1; }
.mine-row { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 6px; }
.mine-progress-text { color: var(--amber); font: 700 10px/1 var(--mono); }
.rock-track { height: 3px; background: rgba(255,255,255,0.08); overflow: hidden; }
.rock-fill {
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--orange), var(--amber-hot));
  box-shadow: 0 0 8px var(--amber);
}
.mine-hint {
  margin-top: 6px;
  color: var(--muted);
  text-align: center;
  font: 600 7px/1.1 var(--mono);
  letter-spacing: 0.07em;
}

.prompt {
  position: absolute;
  left: 50%;
  bottom: 125px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 13px 8px 8px;
  transform: translate(-50%, 8px);
  background: rgba(9, 13, 19, 0.88);
  border: 1px solid rgba(255, 178, 74, 0.36);
  box-shadow: 0 8px 28px rgba(0,0,0,0.45);
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
  white-space: nowrap;
}
.prompt.show { opacity: 1; transform: translate(-50%, 0); }
.prompt .key {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  background: var(--amber);
  color: #1c1207;
  font: 900 11px/1 var(--mono);
  box-shadow: 0 0 18px rgba(255,178,74,0.3);
}
#prompt-text {
  color: #f3f0e8;
  font: 700 10px/1 var(--mono);
  letter-spacing: 0.15em;
}

.toast-stack {
  position: absolute;
  left: 50%;
  top: 165px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  width: min(500px, 80vw);
}
.toast {
  padding: 7px 14px;
  background: rgba(7, 11, 17, 0.86);
  border-left: 2px solid var(--amber);
  color: #e9e2d6;
  font: 600 9px/1.2 var(--mono);
  letter-spacing: 0.08em;
  text-align: center;
  animation: toast-in 0.25s ease both;
  box-shadow: 0 8px 25px rgba(0,0,0,0.35);
}
.toast.bad { border-color: var(--red); color: #ffc8c1; }
.toast.good { border-color: var(--green); color: #cbffda; }
.toast.big {
  padding: 11px 22px;
  font-size: 12px;
  letter-spacing: 0.16em;
  background: rgba(17, 12, 8, 0.92);
  border: 1px solid rgba(255,178,74,0.35);
  border-left: 3px solid var(--amber);
}
@keyframes toast-in {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}
.toast.out { animation: toast-out 0.35s ease both; }
@keyframes toast-out {
  to { opacity: 0; transform: translateY(-6px); }
}

.hud-bottom {
  position: absolute;
  left: 24px;
  right: 24px;
  bottom: 23px;
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 18px;
}
.objective-panel {
  padding: 8px 13px;
  display: flex;
  align-items: baseline;
  gap: 10px;
  max-width: 360px;
}
.objective-flag {
  color: var(--amber);
  font: 700 7px/1 var(--mono);
  letter-spacing: 0.12em;
  white-space: nowrap;
}
#objective-text {
  color: #d6dde0;
  font: 600 10px/1.15 var(--mono);
  letter-spacing: 0.04em;
}
.controls-panel {
  padding: 9px 13px;
  display: flex;
  gap: 14px;
  color: #7f8c92;
  font: 600 7.5px/1 var(--mono);
  letter-spacing: 0.05em;
}
.controls-panel b { color: #dbe3e6; font-weight: 700; }

.status-strip {
  position: absolute;
  left: 24px;
  bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #66757b;
  font: 600 6.5px/1 var(--mono);
  letter-spacing: 0.1em;
}
.status-dot {
  width: 5px; height: 5px;
  background: var(--green);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--green);
}
.status-dot.warn { background: var(--amber); box-shadow: 0 0 8px var(--amber); }
.status-dot.bad { background: var(--red); box-shadow: 0 0 8px var(--red); }
.status-sep { color: #3d4a4f; }

/* Intro */
.intro {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 6vh 7vw;
  background:
    radial-gradient(ellipse at 66% 45%, rgba(26, 34, 44, 0.05) 0%, rgba(4, 7, 12, 0.72) 66%, rgba(3, 6, 10, 0.92) 100%);
  transition: opacity 0.75s ease, visibility 0.75s;
}
.intro.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.intro-scrim {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(4,7,12,0.94) 0%, rgba(4,7,12,0.68) 36%, transparent 68%);
  pointer-events: none;
}
.intro-content {
  position: relative;
  width: min(640px, 70vw);
  animation: intro-in 1s ease both 0.15s;
}
@keyframes intro-in {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}
.intro-eyebrow {
  display: flex;
  align-items: center;
  gap: 11px;
  color: var(--amber);
  font: 700 8px/1 var(--mono);
  letter-spacing: 0.22em;
}
.intro-eyebrow span { width: 34px; height: 1px; background: var(--amber); opacity: 0.6; }
.intro h1 {
  position: relative;
  margin: 20px 0 0;
  color: #eef2f2;
  font: 900 clamp(72px, 10.2vw, 150px)/0.74 var(--condensed);
  letter-spacing: -0.035em;
  text-transform: uppercase;
  text-shadow: 0 8px 50px rgba(0,0,0,0.6);
}
.intro h1 span {
  display: block;
  color: transparent;
  -webkit-text-stroke: 1.5px rgba(255, 178, 74, 0.9);
  text-shadow: 0 0 28px rgba(255, 178, 74, 0.12);
  padding-left: 0.16em;
}
.intro-tag {
  margin: 21px 0 0;
  color: var(--amber-hot);
  font: 700 13px/1 var(--mono);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.intro-copy {
  max-width: 460px;
  margin: 17px 0 0;
  color: #aab6ba;
  font: 500 14px/1.65 var(--condensed);
  letter-spacing: 0.03em;
}
.intro-actions {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-top: 34px;
}
.primary-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 24px;
  padding: 16px 18px 15px 22px;
  border: 0;
  background: var(--amber);
  color: #1a1208;
  font: 800 11px/1 var(--mono);
  letter-spacing: 0.17em;
  cursor: pointer;
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 0 100%);
  transition: background 0.2s ease, transform 0.2s ease;
  pointer-events: auto;
}
.primary-btn:hover { background: var(--amber-hot); transform: translateY(-2px); }
.primary-btn i { font-style: normal; font-size: 16px; line-height: 0.7; }
.primary-btn:active { transform: translateY(0); }
.intro-note {
  max-width: 160px;
  color: #6d7b80;
  font: 600 7px/1.5 var(--mono);
  letter-spacing: 0.1em;
}
.intro-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin-top: 54px;
  border-top: 1px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.12);
  width: min(600px, 66vw);
}
.intro-stats > div {
  padding: 13px 12px 10px;
  background: rgba(9, 13, 19, 0.52);
  display: grid;
  gap: 6px;
}
.intro-stats span { color: var(--amber); font: 700 8px/1 var(--mono); }
.intro-stats b { font: 800 10px/1 var(--mono); letter-spacing: 0.12em; color: #d8e1e4; }
.intro-stats small { color: #748288; font: 500 8px/1.2 var(--mono); }
.intro-footer {
  position: absolute;
  left: 7vw;
  right: 7vw;
  bottom: 22px;
  display: flex;
  justify-content: space-between;
  color: #526168;
  font: 600 7px/1 var(--mono);
  letter-spacing: 0.14em;
}
.intro-coords { color: #6e7d82; }

/* Pause */
.pause {
  position: fixed;
  inset: 0;
  z-index: 45;
  display: grid;
  place-items: center;
  background: rgba(4, 7, 12, 0.62);
  backdrop-filter: blur(6px);
  opacity: 1;
  transition: opacity 0.22s ease, visibility 0.22s;
}
.pause.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.pause-card {
  width: min(390px, calc(100vw - 32px));
  padding: 28px;
  text-align: center;
  border-color: rgba(255,178,74,0.22);
}
.pause-card h2 {
  margin: 10px 0 8px;
  font: 900 44px/1 var(--condensed);
  letter-spacing: 0.16em;
}
.pause-card p { color: var(--muted); font: 500 12px/1.5 var(--condensed); }
.pause-card .primary-btn { margin: 15px 0 10px; }
.pause-controls { color: #66777e; font: 600 7px/1.4 var(--mono); letter-spacing: 0.09em; }
.pause-controls b { color: #c7d3d7; }

/* Modal / menus */
.modal {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(3, 6, 10, 0.72);
  backdrop-filter: blur(8px);
  opacity: 1;
  transition: opacity 0.22s ease, visibility 0.22s;
}
.modal.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.modal-panel {
  position: relative;
  width: min(820px, calc(100vw - 32px));
  max-height: calc(100vh - 48px);
  overflow: auto;
  background:
    linear-gradient(145deg, rgba(20, 27, 36, 0.98), rgba(7, 11, 17, 0.99)),
    repeating-linear-gradient(90deg, transparent 0 70px, rgba(255,255,255,0.015) 70px 71px);
  border: 1px solid rgba(187, 215, 226, 0.24);
  box-shadow: 0 40px 140px rgba(0,0,0,0.75), inset 0 1px 0 rgba(255,255,255,0.08);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
  animation: modal-in 0.3s ease both;
}
@keyframes modal-in {
  from { opacity: 0; transform: translateY(10px) scale(0.995); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.modal-close {
  position: absolute;
  right: 17px;
  top: 17px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(255,255,255,0.16);
  background: rgba(255,255,255,0.03);
  color: #aebdc3;
  font: 300 22px/1 var(--condensed);
  cursor: pointer;
  transition: all 0.2s;
}
.modal-close:hover { background: var(--amber); color: #16100a; border-color: var(--amber); }

.menu-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  padding: 28px 32px 22px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  background:
    radial-gradient(ellipse at 15% 0%, rgba(117, 232, 255, 0.09), transparent 54%),
    linear-gradient(180deg, rgba(255,255,255,0.035), transparent);
}
.menu-head.shop-head {
  background:
    radial-gradient(ellipse at 15% 0%, rgba(255, 178, 74, 0.12), transparent 54%),
    linear-gradient(180deg, rgba(255,255,255,0.035), transparent);
}
.menu-kicker {
  color: var(--cyan);
  font: 700 8px/1 var(--mono);
  letter-spacing: 0.2em;
}
.shop-head .menu-kicker { color: var(--amber); }
.menu-head h2 {
  margin: 7px 0 4px;
  font: 900 38px/0.92 var(--condensed);
  letter-spacing: 0.06em;
}
.menu-head p { margin: 0; color: var(--muted); font: 500 11px/1.3 var(--condensed); letter-spacing: 0.03em; }
.menu-wallet {
  padding: 9px 13px;
  background: rgba(0,0,0,0.3);
  border: 1px solid rgba(255,255,255,0.1);
  text-align: right;
  white-space: nowrap;
}
.menu-wallet span { display: block; color: var(--muted); font: 600 7px/1 var(--mono); letter-spacing: 0.13em; }
.menu-wallet strong { color: var(--green); font: 800 22px/1 var(--condensed); letter-spacing: 0.06em; }
.menu-wallet small { color: var(--muted); font: 600 8px/1 var(--mono); }

.menu-body { padding: 25px 32px 30px; }
.menu-section-title {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin: 0 0 12px;
  color: #c8d3d7;
  font: 700 8px/1 var(--mono);
  letter-spacing: 0.16em;
}
.menu-section-title span { color: #617077; letter-spacing: 0.07em; }
.upgrade-grid { display: grid; grid-template-columns: 1.2fr 0.85fr 0.85fr; gap: 10px; }
.upgrade-card {
  position: relative;
  padding: 17px 16px 15px;
  background: rgba(255,255,255,0.025);
  border: 1px solid rgba(255,255,255,0.1);
  min-height: 200px;
  display: flex;
  flex-direction: column;
}
.upgrade-card.primary-card {
  border-color: rgba(117, 232, 255, 0.28);
  background: linear-gradient(160deg, rgba(117,232,255,0.08), rgba(255,255,255,0.015) 60%);
}
.upgrade-card.locked { opacity: 0.5; }
.upgrade-card .card-num {
  position: absolute;
  right: 13px;
  top: 12px;
  color: #47565d;
  font: 600 8px/1 var(--mono);
}
.card-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  margin-bottom: 10px;
  border: 1px solid rgba(117,232,255,0.35);
  color: var(--cyan);
  font: 800 12px/1 var(--mono);
}
.card-icon.amber { border-color: rgba(255,178,74,0.4); color: var(--amber); }
.upgrade-card h3 { margin: 0 0 6px; font: 800 16px/1 var(--condensed); letter-spacing: 0.06em; }
.upgrade-card p { margin: 0 0 11px; color: #87949a; font: 500 10px/1.45 var(--condensed); flex: 1; }
.card-stat {
  display: flex;
  justify-content: space-between;
  padding: 6px 0;
  border-top: 1px solid rgba(255,255,255,0.07);
  color: #7e8d93;
  font: 600 7px/1 var(--mono);
  letter-spacing: 0.07em;
}
.card-stat b { color: #d4dfe2; }
.buy-btn {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  width: 100%;
  margin-top: 11px;
  padding: 10px 12px;
  border: 1px solid rgba(117,232,255,0.38);
  background: rgba(117,232,255,0.09);
  color: var(--cyan);
  font: 800 8px/1 var(--mono);
  letter-spacing: 0.1em;
  cursor: pointer;
  transition: all 0.18s;
}
.buy-btn:hover { background: var(--cyan); color: #06151a; }
.buy-btn:disabled { border-color: rgba(255,255,255,0.1); background: rgba(255,255,255,0.02); color: #5b6a71; cursor: not-allowed; }
.buy-btn.owned { border-color: rgba(145,247,177,0.22); background: rgba(145,247,177,0.05); color: var(--green); cursor: default; }
.buy-btn.amber { border-color: rgba(255,178,74,0.42); background: rgba(255,178,74,0.08); color: var(--amber); }
.buy-btn.amber:hover { background: var(--amber); color: #1a1208; }
.buy-btn.amber:disabled { border-color: rgba(255,255,255,0.1); background: rgba(255,255,255,0.02); color: #5b6a71; }
.card-note { margin-top: 8px; color: #66757b; font: 500 7.5px/1.3 var(--mono); letter-spacing: 0.02em; }

.fuel-gauge {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px 18px;
  align-items: end;
  padding: 17px 19px;
  margin-bottom: 18px;
  border: 1px solid rgba(255,178,74,0.2);
  background: rgba(255,178,74,0.02);
}
.fuel-gauge .gauge-track {
  grid-column: 1 / -1;
  height: 12px;
  padding: 2px;
  border: 1px solid rgba(255,255,255,0.12);
  background: rgba(0,0,0,0.3);
}
.fuel-gauge .gauge-fill {
  height: 100%;
  width: 50%;
  background: linear-gradient(90deg, #c74f14, var(--amber) 70%, var(--amber-hot));
  box-shadow: 0 0 14px rgba(255,178,74,0.3);
  transition: width 0.25s ease;
}
.fuel-gauge .big-number { color: #e9eef0; font: 800 27px/1 var(--condensed); letter-spacing: 0.03em; }
.fuel-gauge .big-number small { color: var(--muted); font: 700 10px/1 var(--mono); }
.fuel-gauge .micro-label { align-self: start; }
.fuel-gauge .fuel-note { color: #7d8a90; font: 500 9px/1.4 var(--condensed); text-align: right; }

.shop-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.shop-card {
  padding: 18px 16px 15px;
  border: 1px solid rgba(255,255,255,0.1);
  background: linear-gradient(160deg, rgba(255,178,74,0.045), rgba(255,255,255,0.012));
  display: flex;
  flex-direction: column;
}
.shop-card.featured { border-color: rgba(255,178,74,0.3); }
.shop-card h3 { margin: 11px 0 5px; font: 800 22px/1 var(--condensed); letter-spacing: 0.03em; }
.shop-card .litres { color: var(--muted); font: 600 8px/1 var(--mono); letter-spacing: 0.1em; }
.shop-card p { flex: 1; margin: 11px 0; color: #849197; font: 500 9px/1.45 var(--condensed); }
.shop-card .price { color: var(--amber-hot); font: 800 14px/1 var(--mono); }
.barrel-icon {
  width: 36px; height: 42px;
  border: 1px solid rgba(255,178,74,0.45);
  border-radius: 4px;
  background: repeating-linear-gradient(180deg, rgba(255,178,74,0.12) 0 3px, transparent 3px 10px);
  position: relative;
}
.barrel-icon::before, .barrel-icon::after {
  content: ""; position: absolute; left: -3px; right: -3px; height: 2px; background: rgba(255,178,74,0.55);
}
.barrel-icon::before { top: 10px; }
.barrel-icon::after { bottom: 10px; }
.shop-foot {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid rgba(255,255,255,0.08);
  color: #6e7d82;
  font: 500 8px/1.5 var(--mono);
  letter-spacing: 0.04em;
}
.shop-foot b { color: #bdc9cd; }

.menu-tip {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  margin-top: 18px;
  padding: 11px 13px;
  background: rgba(255,255,255,0.025);
  border-left: 2px solid rgba(117,232,255,0.45);
  color: #829096;
  font: 500 9px/1.5 var(--condensed);
}
.menu-tip b { color: #cfdadc; }

/* End */
.end-screen {
  padding: 42px 40px 38px;
  text-align: center;
  background:
    radial-gradient(circle at 50% 42%, rgba(255, 113, 31, 0.24), transparent 42%),
    linear-gradient(180deg, rgba(16,11,8,0.98), rgba(5,8,13,0.99));
}
.end-screen .menu-kicker { color: var(--amber); }
.end-screen h2 {
  margin: 14px 0 3px;
  font: 900 64px/0.85 var(--condensed);
  letter-spacing: 0.05em;
  color: #fff0dd;
  text-shadow: 0 0 40px rgba(255, 116, 33, 0.45);
}
.end-screen .end-sub { color: var(--amber); font: 700 9px/1 var(--mono); letter-spacing: 0.2em; }
.end-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin: 30px 0 26px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.1);
}
.end-grid > div { padding: 14px 9px; background: rgba(8,10,14,0.8); }
.end-grid span { display: block; color: #7f8b90; font: 600 7px/1 var(--mono); letter-spacing: 0.1em; }
.end-grid strong { display: block; margin-top: 6px; color: #f1e9dd; font: 800 19px/1 var(--condensed); }
.end-copy { max-width: 530px; margin: 0 auto 24px; color: #b7a99a; font: 500 12px/1.6 var(--condensed); }
.end-screen .primary-btn { margin: auto; }

.fade {
  position: fixed;
  inset: 0;
  z-index: 30;
  pointer-events: none;
  background: #030507;
  opacity: 0;
  transition: opacity 0.6s ease;
}
.fade.on { opacity: 1; }
.flash {
  position: fixed;
  inset: 0;
  z-index: 31;
  pointer-events: none;
  background: #fff3d9;
  opacity: 0;
}
.flash.fire { animation: flash-fire 0.45s ease-out both; }
@keyframes flash-fire {
  0% { opacity: 0.7; }
  100% { opacity: 0; }
}

.rotate-warning { display: none; }

@media (max-width: 1060px) {
  .hud-top { grid-template-columns: 1fr 1.35fr; }
  .resource-panel { grid-column: 1 / -1; justify-content: flex-start; gap: 14px; min-height: 46px; }
  .resource { flex: 1; }
  .depth-panel { grid-column: 2; }
  .brand-panel { grid-column: 1; }
  .controls-panel { flex-wrap: wrap; max-width: 390px; justify-content: flex-end; }
  .intro-content { width: min(610px, 82vw); }
}

@media (max-width: 760px) {
  .hud-top { left: 10px; right: 10px; top: 10px; gap: 7px; }
  .brand-panel { min-height: 48px; padding: 8px 10px; }
  .brand-sub { display: none; }
  .brand-name { font-size: 16px; }
  .brand-mark { width: 30px; height: 30px; font-size: 10px; }
  .depth-panel { padding: 8px 10px; }
  .depth-value { font-size: 19px; }
  .depth-target, .depth-meta span:last-child { display: none; }
  .resource-panel { min-height: 42px; padding: 6px 8px; }
  .resource strong { font-size: 14px; }
  .resource-icon { width: 21px; height: 21px; }
  .hud-bottom { left: 10px; right: 10px; bottom: 12px; }
  .controls-panel { display: none; }
  .objective-panel { max-width: calc(100vw - 20px); }
  .status-strip { display: none; }
  .cue { display: none; }
  .prompt { bottom: 95px; }
  .intro { padding: 30px 25px; justify-content: flex-end; padding-bottom: 70px; }
  .intro-scrim { background: linear-gradient(0deg, rgba(4,7,12,0.98) 8%, rgba(4,7,12,0.7) 58%, transparent 100%); }
  .intro-content { width: 100%; }
  .intro h1 { font-size: clamp(54px, 18vw, 96px); }
  .intro-copy { font-size: 12px; max-width: 340px; }
  .intro-stats { grid-template-columns: repeat(2, 1fr); width: 100%; margin-top: 28px; }
  .intro-actions { flex-wrap: wrap; gap: 12px; margin-top: 23px; }
  .intro-footer { display: none; }
  .intro-tag { font-size: 9px; }
  .mine-readout { width: 210px; }
  .menu-head { padding: 23px 20px 18px; }
  .menu-body { padding: 18px 20px 22px; }
  .menu-head h2 { font-size: 29px; }
  .menu-wallet { display: none; }
  .upgrade-grid, .shop-grid { grid-template-columns: 1fr; }
  .upgrade-card { min-height: auto; }
  .end-screen { padding: 35px 20px 28px; }
  .end-screen h2 { font-size: 48px; }
  .end-grid { grid-template-columns: repeat(2, 1fr); }
  .modal { padding: 10px; }
  .modal-panel { max-height: calc(100vh - 20px); }
}

@media (orientation: portrait) and (max-width: 700px) {
  .rotate-warning {
    display: flex;
    position: fixed;
    left: 12px;
    right: 12px;
    bottom: 14px;
    z-index: 60;
    align-items: center;
    gap: 10px;
    padding: 9px 12px;
    border: 1px solid rgba(255,178,74,0.3);
    background: rgba(7,10,15,0.9);
    color: var(--amber);
    font: 700 7px/1.2 var(--mono);
    letter-spacing: 0.09em;
  }
  .rotate-warning span { font-size: 18px; }
  .rotate-warning small { color: #7c898e; margin-left: auto; max-width: 150px; text-align: right; }
  body.playing .rotate-warning { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; }
}

