// ---------------------------------------------------------------------------
// Site construction
// ---------------------------------------------------------------------------
const lights = new THREE.Group(); scene.add(lights);
const hemi = new THREE.HemisphereLight(0xb9c8d0, 0x26180e, 1.2); scene.add(hemi);
