const interactions = [
  {id:'lab',label:'ENTER SCIENCE LAB',pos:new THREE.Vector3(-12,0,-13),radius:4},
  {id:'shop',label:'OPEN DIESEL DEPOT',pos:new THREE.Vector3(12,0,-13),radius:4},
